import type { EntityInput, IdeaInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";

/**
 * Protocol upgrades across the care pathway outside radiotherapy and surgery: changes to how existing care is
 * delivered rather than new treatments. Precision and protocol-upgrades run, 20 October 2026, facet 7.
 *
 * Every upgrade is an idea record tagged `protocol-upgrade` with exactly one adoption tier:
 *   upgrade:proven-unevenly-used  randomised or guideline-level evidence of benefit, yet not routine everywhere;
 *   upgrade:promising             some clinical evidence, not yet settled;
 *   upgrade:untested              plausible, with the trial that would settle it named in `test`.
 * and an evidence grade `evidence:<grade>` on the src/data/complementary.ts model (strong, moderate, insufficient,
 * no-benefit, harm). `precision` is added where the upgrade is a gain in precision (a test or score that decides who
 * gets what). An adoption gap is stated only where a survey, an audit or a registry measured it; otherwise the record
 * says that adoption has not been measured.
 *
 * Most topics on the brief already had an idea record, several of them twice. Those were supplemented in their own
 * files rather than written again, and carry the same tags: reflex genomic profiling, DPYD and other pharmacogenomic
 * testing, geriatric assessment, weekly electronic symptom reporting, scalp cooling, structured exercise after colon
 * cancer, early palliative care, question prompt lists, recorded consultations, decision aids, risk-stratified
 * follow-up, broader trial eligibility, financial hardship screening, olanzapine antiemetics and fertility referral.
 * The two weekly symptom reporting ideas said that the trials showed people lived longer; the largest trial, built to
 * test exactly that, found no survival difference, and both records now say so, in line with
 * `rejuv-measure-epro-as-treatment`. Survivorship care plans are not tagged as an upgrade: the randomised trial of
 * them found no benefit (`rejuv-access-survivorship-care-us`), and the idea that would generate them automatically
 * gained a note saying so.
 *
 * This file holds the seven upgrades that had no record. Every figure was read from the abstract or full text of the
 * source beside it, and every DOI was resolved through Europe PMC before use. UK spelling.
 *
 * The protocol fill round of 11 November 2026 added ten more at the end of the file, each linked from the care protocol
 * in src/data/protocols/ whose sources exposed the gap.
 */

const asOf = "2026-10-20";
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

type Tier = "proven-unevenly-used" | "promising" | "untested";
const T = (tier: Tier, grade: EvidenceGrade, extra: string[] = []) => ["protocol-upgrade", `upgrade:${tier}`, `evidence:${grade}`, ...extra];
const idea = (x: Omit<IdeaInput, "kind" | "asOf">): IdeaInput => ({ kind: "idea", asOf, ...x });

