const ideas: IdeaInput[] = [
  idea({ id: "idea-upgrade-oral-anticancer-medicine-adherence-programme", name: "A structured support programme for everyone taking cancer tablets at home", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care", "chemotherapy", "targeted-therapy"], tags: T("promising", "moderate"),
    tldr: "More cancer treatment now comes as tablets taken at home, where nobody sees missed doses or side effects building up. A nursing guideline recommends a structured programme: a check at the start of who may struggle, teaching, follow-up calls from the team, and coaching. The trials behind it are small and mixed, so this is promising rather than settled.",
    summary: "The guideline. The Oncology Nursing Society's 2022 guideline, built with GRADE methods and patient representatives, suggested an adherence risk assessment, education addressing adherence, ongoing assessment, proactive follow-up, coaching and motivational interviewing in addition to usual care, and suggested that services implement a structured oral anticancer medication programme.\n\nThe evidence under it. The systematic review written for that guideline concluded that \"risk assessment, ongoing or periodic assessment, proactive follow-up, motivational interviewing, or structured programs may improve adherence\", while education or coaching alone \"may improve or have little to no effect\", and interactive technology was no better than non-interactive. An earlier scoping review found 56 studies, of which 14 were randomised trials and 33 enrolled fewer than 100 patients; fewer than half of the studies with a comparison group (44.7 per cent) reported a statistically significant improvement in adherence or persistence, and the programmes that did best were pharmacist-led and built in regular monitoring with follow-up by a clinician.\n\nWhat is not known. How many services run such a programme has not been measured in any survey OnCo found, and no trial has yet shown that better adherence through these programmes changes survival or admissions. The upgrade is cheap and low-risk; the evidence says it probably helps adherence and leaves the size of the effect open.",
    hypothesis: "A structured programme for oral anticancer medicines (a risk assessment at the first prescription, a teaching session, calls from the team in weeks one, two and four, and pharmacist review at every dose change) raises the proportion of patients who take at least 90 per cent of prescribed doses by at least ten percentage points over current teaching, and reduces unplanned admissions for toxicity.",
    rationale: "The shift to tablets moved the work of giving treatment from the day unit to the kitchen table without moving the monitoring with it. The components that the review found most promising are the ones that restore contact: a team member calling at set times, and someone checking doses whenever they change.",
    test: "A cluster-randomised trial across oncology practices starting patients on oral kinase inhibitors, CDK4/6 inhibitors or capecitabine, with adherence from dispensing records at six months as the primary endpoint and unplanned admissions, dose intensity and patient-reported side effects as secondary endpoints, against each practice's current teaching.",
    technologies: ["kinase-inhibitors", "cdk46-inhibitor"], drugs: ["capecitabine"], bottlenecks: ["b-toxicity-qol", "b-care-fragmentation"],
    related: ["idea-acc-pharmacist-interaction-review-oral-anticancer", "idea-tr1-start-low-titrate-up-oral-agents"],
    links: [ONS_OAM_2022, WASEEM_2022, ROSENBERG_2020] }),

  idea({ id: "idea-upgrade-hand-foot-cooling-compression-during-taxanes", name: "Frozen gloves or tight surgical gloves offered during every weekly taxane infusion", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care", "chemotherapy"], tags: T("promising", "moderate"),
    tldr: "Cooling the hands and feet, or squeezing them in tight surgical gloves, during paclitaxel infusions narrows blood vessels while the drug level peaks. In one randomised trial, moderate or worse nerve damage in the treated hand fell from 50 to 29 per cent with cooling; a larger trial of frozen gloves and socks missed its main target but found less numbness.",
    summary: "The positive trial. POLAR randomised 122 women with early breast cancer receiving weekly paclitaxel or nab-paclitaxel to cooling (a frozen glove) or compression (two surgical gloves one size smaller than a tight fit) of the dominant hand, 30 minutes before, during and after each infusion, with the other hand left untreated as the control; 101 were analysed. Grade 2 or higher sensory neuropathy occurred in 29 per cent of cooled hands against 50 per cent of untreated hands, and in 24 per cent of compressed hands against 38 per cent. Neuropathy was the main reason for stopping treatment in 16 of the 24 who stopped.\n\nThe trial that did not reach its target. CryoPac randomised 268 patients receiving taxanes to frozen gloves and socks at every infusion or to usual care; 217 were analysed. Neuropathy on the Total Neuropathy Score at the end of treatment was 74 per cent with cryotherapy and 84 per cent with usual care (P = .071), so the primary endpoint was not met. Patient-reported tingling and numbness in the hands, numbness in the feet and trouble handling small objects were all lower with cryotherapy, there was no difference in grade 2 or higher neuropathy by the clinician scale, and compliance with the gloves and socks was 67 per cent. A smaller self-controlled study (Hanai, 2018) also favoured frozen gloves and socks on the treated side.\n\nWhere guidance stands. The 2020 ASCO guideline on chemotherapy nerve damage states that no agents are recommended for prevention; it was written before both randomised trials above. Adoption has not been measured. The harms reported are discomfort and the risk of cold injury with prolonged contact, and the trials enrolled patients on taxanes only, so the result does not transfer to other drugs that damage nerves.",
    hypothesis: "Offering every patient starting weekly paclitaxel a choice of cooling or compression of hands and feet reduces patient-reported neuropathy six months after the last dose by a clinically meaningful margin, without lowering the dose of taxane delivered.",
    rationale: "Neuropathy from taxanes is common, can last for years and is a leading reason for stopping treatment early. Both interventions use equipment that costs a few pounds and add no drug, so a modest benefit would justify routine use if it holds up; the split between the two trials is the reason it is graded promising rather than proven.",
    test: "A multicentre randomised trial in patients starting weekly paclitaxel comparing usual care with cooling or compression of both hands and feet, with patient-reported neuropathy (EORTC QLQ-CIPN20) six months after the last dose as the primary endpoint, because persistence is what matters to the person and neither published trial was powered for it; delivered taxane dose and adherence to the gloves as secondary endpoints.",
    technologies: ["frozen-gloves-compression-taxane"], terms: ["peripheral-neuropathy"], drugs: ["paclitaxel", "docetaxel"], cancers: ["breast-hr-positive"], keyPapers: ["paper-hanai-j-natl-cancer-inst"],
    bottlenecks: ["b-toxicity-qol"], related: ["idea-moon-neuropathy-prevention-programme"],
    links: [POLAR_2025, CRYOPAC_2026, HANAI_2018, ASCO_CIPN_2020] }),

  idea({ id: "idea-upgrade-oral-cryotherapy-with-bolus-chemotherapy", name: "Ice chips in the chair for every bolus fluorouracil and high-dose melphalan infusion", maturity: "being-tested-at-scale", actor: "clinic", cost: "small", horizonYears: 1,
    sections: ["supportive-care", "chemotherapy"], tags: T("proven-unevenly-used", "strong"),
    tldr: "Holding ice chips in the mouth for half an hour around a quick injection of fluorouracil, or high-dose melphalan before a stem cell transplant, cools the mouth while the drug level peaks. A review of 14 trials found it prevents mouth ulcers in about one in four people given fluorouracil, and a guideline recommends it. How often it is offered is not measured.",
    summary: "The evidence. The 2015 Cochrane review included 14 randomised trials with 1,280 participants, all at high risk of bias, mostly in chemotherapy rather than head and neck radiotherapy. For adults receiving fluorouracil-based chemotherapy for solid cancers, oral cryotherapy probably reduces oral mucositis of any severity (risk ratio 0.61, 95 per cent confidence interval 0.52 to 0.72, five studies, moderate-quality evidence), with a number needed to treat of 4, and probably reduces severe mucositis (risk ratio 0.40, 0.27 to 0.61), number needed to treat 6. For high-dose melphalan before haematopoietic stem cell transplantation, severe mucositis is probably reduced (risk ratio 0.38, 0.20 to 0.72). Adverse effects were minor and rare.\n\nThe guideline. The 2020 MASCC/ISOO mucositis guideline states: \"The panel recommends using 30 min of oral cryotherapy to prevent OM in patients receiving bolus 5-FU CT during the infusion of the CT\" and \"recommends using oral cryotherapy to prevent OM in patients undergoing autologous HSCT when the conditioning includes high-dose melphalan.\"\n\nThe limits. The rationale rests on a short peak in drug level, which a continuous infusion or a daily tablet does not produce, so the recommendation covers bolus fluorouracil and high-dose melphalan and nothing wider. OnCo found no survey or audit of how often eligible patients are offered it, so the gap between recommendation and practice is not measured; the tier records strong evidence for an intervention that costs a cup of ice.",
    hypothesis: "A standing order for oral cryotherapy attached to every bolus fluorouracil and high-dose melphalan prescription raises delivery to eligible patients above 90 per cent and lowers the incidence of severe mucositis in those units towards the trial estimates.",
    rationale: "When the evidence and the guideline are settled and the intervention is ice, the only failure left is that nobody brings the cup. An order-set default removes the step that depends on memory.",
    test: "An audit, across chemotherapy day units and transplant units, of the proportion of eligible infusions given with oral cryotherapy, followed by a stepped introduction of the standing order with severe mucositis on a standard scale as the outcome.",
    technologies: ["oral-cryotherapy-mucositis"], terms: ["mucositis"], drugs: ["fluorouracil", "melphalan"], keyPapers: ["paper-riley-cochrane-database-syst-rev", "paper-elad-cancer"],
    bottlenecks: ["b-toxicity-qol", "b-knowledge-diffusion"], related: ["idea-moon-mucositis-taste-programme"],
    links: [COCHRANE_CRYO_2015, MASCC_2020] }),

  idea({ id: "idea-upgrade-clot-risk-score-and-preventive-anticoagulation", name: "A blood clot risk score at the start of chemotherapy, with preventive anticoagulation offered to those at higher risk", maturity: "being-tested-at-scale", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care", "chemotherapy"], tags: T("proven-unevenly-used", "moderate", ["precision"]),
    tldr: "People with cancer get blood clots more often than others. A score built from the cancer type and routine blood tests picks out those at higher risk, and in two placebo-controlled trials a low-dose blood-thinning tablet reduced clots but caused more bleeding. United States guidance says it may be offered; surveys in the Netherlands and China found most specialists do not use the score.",
    summary: "The score. The Khorana score was derived in 2,701 outpatients starting chemotherapy and validated in 1,365 more. It gives points for the site of the cancer (two for very high-risk sites, one for high-risk sites) and one point each for a platelet count of 350 x 10^9/L or more, haemoglobin below 100 g/L or use of an erythropoiesis-stimulating agent, a white cell count above 11 x 10^9/L, and a body mass index of 35 or more. Symptomatic clots over a median 2.5 months occurred in 0.8 and 0.3 per cent of the low-risk group and 7.1 and 6.7 per cent of the high-risk group in the two cohorts.\n\nThe trials. AVERT randomised 574 patients with a score of 2 or more starting chemotherapy to apixaban 2.5 mg twice daily or placebo: clots occurred in 4.2 per cent against 10.2 per cent (hazard ratio 0.41), and major bleeding in 3.5 per cent against 1.8 per cent (hazard ratio 2.00). CASSINI randomised 841 patients to rivaroxaban 10 mg daily or placebo: the primary endpoint at 180 days was 6.0 against 8.8 per cent (hazard ratio 0.66, P = 0.10), which was not statistically significant; during the period patients were actually taking the drug it was 2.6 against 6.4 per cent (hazard ratio 0.40), with major bleeding 2.0 against 1.0 per cent.\n\nThe guidance. The 2019 ASCO update, published in 2020, states that clinicians \"may offer thromboprophylaxis with apixaban, rivaroxaban, or LMWH to selected high-risk outpatients with cancer\", that thromboprophylaxis is not routinely recommended for all outpatients, and that patients should be periodically assessed for risk; the 2023 update revised the surgical and treatment recommendations.\n\nThe measured gap. In a 2025 Dutch survey of 38 medical oncologists treating pancreatic cancer, 63 per cent had never prescribed thromboprophylaxis to ambulatory patients on chemotherapy, 11 per cent used the Khorana score and 3 per cent always discussed clot risk with patients; the commonest reason given was the lack of a national guideline recommendation. In a 2025 survey of 235 physicians in Chinese tertiary hospitals treating advanced lung cancer, 57.8 per cent routinely used the score and 49.4 per cent said they were familiar with it.",
    hypothesis: "Calculating the score automatically at the first chemotherapy prescription and presenting the option of prophylaxis with its bleeding risk to every patient scoring 2 or more increases informed prophylaxis decisions and lowers symptomatic clots in that group, without a net rise in major bleeding.",
    rationale: "The score uses numbers already in the record, so the only reason it is not calculated is that nobody is prompted to. The trials make this a preference-sensitive choice, fewer clots against more bleeding, which is a reason to put the choice in front of the patient rather than to make it silently either way.",
    test: "A stepped-wedge trial across chemotherapy units introducing an automatic score with a decision prompt, measuring the proportion of high-risk patients offered prophylaxis, symptomatic clots and major bleeding at six months.",
    technologies: ["cancer-associated-thrombosis"], terms: ["vte"], cancers: ["pancreatic", "nsclc"], keyPapers: ["paper-key-j-clin-oncol"],
    bottlenecks: ["b-toxicity-qol", "b-knowledge-diffusion"],
    links: [KHORANA_2008, AVERT_2019, CASSINI_2019, ASCO_VTE_2020, ASCO_VTE_2023, WILLEMS_2026, WANG_2026] }),

  idea({ id: "idea-upgrade-hepatitis-b-testing-before-systemic-treatment", name: "Hepatitis B blood tests before anyone starts systemic cancer treatment, with antiviral tablets for those who need them", maturity: "being-tested-at-scale", actor: "clinic", cost: "small", horizonYears: 1,
    sections: ["supportive-care", "chemotherapy"], tags: T("proven-unevenly-used", "strong"),
    tldr: "Hepatitis B can lie quiet for decades and flare when cancer treatment weakens the immune system, sometimes fatally. An American Society of Clinical Oncology opinion says everyone starting systemic cancer treatment should be tested first, and antiviral tablets prevent most flares. Across 29 studies, 57 per cent of patients were tested before chemotherapy.",
    summary: "The recommendation. The 2020 ASCO provisional clinical opinion states that \"all patients anticipating systemic anticancer therapy should be tested for HBV by 3 tests\" (hepatitis B surface antigen, core antibody and surface antibody), \"but anticancer therapy should not be delayed\". People with chronic infection receiving any systemic anticancer therapy should receive antiviral prophylaxis during and for at least 12 months after treatment; people with past infection receiving high-risk treatment such as anti-CD20 antibodies or stem cell transplantation should receive prophylaxis or, where follow-up can be relied on, careful monitoring.\n\nWhy it works. A 2008 systematic review of 14 studies (two randomised) in surface-antigen-positive patients receiving chemotherapy found relative risks for reactivation and hepatitis between 0.00 and 0.21 with preventive lamivudine; hepatic failure occurred in none of 108 patients given it against 21 of 162 controls, and deaths attributed to hepatitis B in 4 of 208 against 27 of 394. A randomised trial in 121 surface-antigen-positive patients with diffuse large B-cell lymphoma receiving R-CHOP then showed entecavir outperformed lamivudine: hepatitis 0 against 13.3 per cent, reactivation 6.6 against 30 per cent, chemotherapy disrupted 1.6 against 18.3 per cent.\n\nThe measured gap. A 2024 meta-analysis of 29 studies found a pooled screening rate before chemotherapy of 57 per cent, rising from 37 per cent in 2006 to 2010 to 69 per cent in 2016 to 2020. Rates were 89 per cent in high-prevalence countries and 49 per cent in low-prevalence ones, 65 per cent in blood cancers against 37 per cent in solid tumours, and 68 per cent with rituximab-containing regimens against 45 per cent without.",
    hypothesis: "Making the three hepatitis B tests a hard stop in the first systemic therapy order set, with an automatic referral pathway for positive results, raises pre-treatment testing above 95 per cent in solid-tumour as well as blood cancer services and eliminates avoidable reactivation.",
    rationale: "The test is cheap, the treatment is a daily tablet, and the harm it prevents can be fatal and interrupts the cancer treatment itself. The gap is largest exactly where clinicians assume the virus is rare, which is where a default does the most good.",
    test: "Implementation in a solid-tumour chemotherapy service with pre-treatment testing rate as the primary measure and reactivation events, prophylaxis given to those eligible, and any delay to the start of cancer treatment as secondary measures, compared with the service's own baseline.",
    terms: ["lymphoma-tx-hepatitis-b-reactivation", "hbv-hcv"], drugs: ["rituximab"],
    bottlenecks: ["b-toxicity-qol", "b-care-fragmentation"],
    links: [ASCO_HBV_2020, MAUNG_2024, LOOMBA_2008, HUANG_2014] }),

  idea({ id: "idea-upgrade-stop-smoking-treatment-at-diagnosis", name: "Stop-smoking treatment offered to every person who smokes at a cancer diagnosis, as part of cancer care", maturity: "being-tested-at-scale", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care", "prevention"], tags: T("proven-unevenly-used", "moderate"),
    tldr: "Quitting smoking around a lung cancer diagnosis is linked to longer survival, and in a randomised trial of people newly diagnosed with cancer, longer counselling with free medicine raised the six-month quit rate from about one in five to one in three. In a survey of 762 accredited United States cancer programmes, 17.6 per cent regularly prescribed stop-smoking medicine.",
    summary: "The randomised trial. Park and colleagues randomised 303 people who smoked and had recently been diagnosed with one of eight common cancers at two United States cancer centres. Both groups received four weekly telephone counselling sessions and medication advice; the intensive group also received further sessions over the following months and their choice of free nicotine replacement, bupropion or varenicline. Biochemically confirmed quit rates at six months were 34.5 per cent against 21.5 per cent (odds ratio 1.92).\n\nWhat quitting is associated with. A 2022 meta-analysis of 21 observational studies including more than 10,000 people with lung cancer found that quitting at or around diagnosis was associated with better overall survival (summary relative risk 0.71, 95 per cent confidence interval 0.64 to 0.80), consistently in non-small-cell and small-cell disease. These are cohort comparisons, not randomised ones, which is why the grade here is moderate.\n\nThe measured gap. A baseline survey of 762 Commission on Cancer and breast-centre accredited programmes found 89.9 per cent regularly asked about smoking and 71.2 per cent advised quitting, but 41.3 per cent regularly helped patients quit, 18.2 per cent provided individual counselling and 17.6 per cent regularly prescribed medication; lack of trained staff (68.8 per cent) and of designated specialists (61.9 per cent) were the commonest barriers. Across 28 National Cancer Institute centres funded to build tobacco treatment programmes, a median of 96 per cent of patients were screened for tobacco use, but median reach, the proportion of people who smoked receiving any evidence-based treatment, was 15.4 per cent.",
    hypothesis: "An opt-out tobacco treatment pathway at cancer diagnosis, in which everyone recorded as smoking is referred to a tobacco specialist and offered medication unless they decline, raises treatment reach above 50 per cent and six-month verified abstinence above the rates seen with ask-and-advise practice.",
    rationale: "The screening step already happens almost everywhere; the gap is between knowing someone smokes and treating it. The trial shows what sustained treatment achieves in exactly this population, and the surveys show where the pathway breaks.",
    test: "A cluster-randomised comparison of opt-out referral against usual ask-and-advise practice across cancer centres, with reach and biochemically verified abstinence at six months as co-primary endpoints and treatment complications and survival as long-term outcomes.",
    technologies: ["smoking-cessation-after-diagnosis"], terms: ["smoking-cessation"], cancers: ["nsclc"],
    bottlenecks: ["b-prevention-adoption", "b-knowledge-diffusion"], related: ["idea-prev-opt-out-cessation-in-lung-screening", "idea-prev-cytisine-essential-medicine"],
    links: [PARK_2020, CAINI_2022, OSTROFF_2024, HOHL_2023] }),

  idea({ id: "idea-upgrade-nutrition-risk-screening-at-treatment-start", name: "Nutrition risk screening when cancer treatment starts, with a dietitian plan for everyone who screens positive", maturity: "being-tested-at-scale", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care", "nutrition-lifestyle"], tags: T("proven-unevenly-used", "moderate"),
    tldr: "Weight loss and poor eating during cancer treatment are common and often missed. A European guideline strongly recommends checking intake and weight from diagnosis, and in a randomised trial of hospital patients with cancer at nutritional risk, tailored nutrition support lowered 30-day deaths from 19.9 to 14.1 per cent. Of 100 Italian centres surveyed, 31 assessed every patient.",
    summary: "The guideline. The ESPEN practical guideline on clinical nutrition in cancer opens with the recommendation \"to regularly evaluate nutritional intake, weight change, and body mass index (BMI), beginning with cancer diagnosis and repeated depending on the stability of the clinical situation\", graded as a strong recommendation.\n\nThe trial. In a preplanned secondary analysis of the Swiss multicentre EFFORT trial, 506 inpatients whose main admission diagnosis was cancer and who were at nutritional risk on the NRS 2002 screen were randomised to protocol-guided individual nutritional support or standard hospital food. Thirty-day mortality was 14.1 per cent against 19.9 per cent (adjusted odds ratio 0.57, 95 per cent confidence interval 0.35 to 0.94), and function and quality of life also improved; each additional point of nutritional risk predicted higher mortality over 180 days. This is one trial, in hospital inpatients, analysed as a subgroup, which is why the grade is moderate; outpatient evidence for screening itself is weaker.\n\nThe measured gap. Of 165 Italian oncology centres surveyed by CIPOMO, 100 responded: 67 routinely assessed nutrition at diagnosis but only 31 did so for every patient, 69 per cent used a validated screening tool, and systematic reassessment during treatment was reported by 15 per cent.",
    hypothesis: "A validated nutrition screen recorded at the first treatment visit and repeated at each cycle, with automatic dietitian referral for a positive screen, reduces unplanned weight loss, treatment interruptions and unplanned admissions in the screened population.",
    rationale: "Malnutrition develops in the gap between appointments and is easiest to treat early. Screening costs a set of scales and two minutes; the evidence gap is in outpatients, which is exactly where most treatment now happens.",
    test: "A cluster-randomised trial in outpatient chemotherapy units of routine screening with automatic dietitian referral against current practice, with unplanned weight loss of 5 per cent or more and completion of planned treatment as co-primary endpoints.",
    technologies: ["nutrition-screening-mnt", "oncology-nutrition"], terms: ["malnutrition-screening", "cachexia"], keyPapers: ["paper-muscaritoli-clin-nutr", "paper-schuetz-lancet"],
    bottlenecks: ["b-cachexia-supportive"], related: ["idea-nl-dietitian-in-every-mdt", "idea-pdac-enzyme-replacement-prescribing-by-default"],
    links: [ESPEN_2021, BARGETZI_2021, GROSSO_2026] }),

  idea({ id: "idea-upgrade-prophylactic-antimuscarinic-when-dying-recognised", name: "An antimuscarinic started when dying is recognised, to prevent the death rattle rather than treat it", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 3,
    sections: ["supportive-care"], tags: T("promising", "moderate"),
    tldr: "Noisy breathing in the last days of life, often called the death rattle, distresses many families. Guidelines give a drug to dry the secretions only once the noise has started and is causing distress. In one Dutch trial, starting the drug as soon as dying was recognised halved how often the rattle appeared.",
    summary: "Current practice. NICE NG31 (2015) asks teams to reassure families, consider non-drug measures, and consider atropine, glycopyrronium or hyoscine only once noisy secretions are distressing the dying person; the Korean last-days guideline (2020) grades drug treatment C IIb. Neither recommends prevention.\n\nThe trial. SILENCE randomised 162 people in six Dutch hospices, at the point the dying phase was recognised, to subcutaneous scopolamine butylbromide 20 mg four times a day or placebo (157 analysed). A death rattle of grade 2 or more occurred in 13% against 27% (difference 14%, 95% CI 2% to 27%). Restlessness was 28% against 23%, dry mouth 10% against 15% and urinary retention 23% against 17% among those assessed. It is one trial, in hospices, of one drug.\n\nThe gap. No guideline read has adopted prophylaxis, and how often it is used has not been measured.",
    hypothesis: "Starting subcutaneous scopolamine butylbromide when the dying phase is recognised, outside hospices as well as in them, reduces the proportion of people who develop a distressing death rattle and family distress at the bedside, without a meaningful rise in restlessness or urinary retention.",
    rationale: "The drugs are cheap, already in anticipatory medicine boxes and given by the same route; the only change is timing. The one randomised trial is positive on its primary outcome, so the question is whether the effect holds in hospitals and at home and whether it matters to families.",
    test: "A pragmatic randomised or stepped-wedge trial across hospital wards and community palliative care of prophylactic against on-demand antimuscarinic, with death rattle grade, bereaved family distress and anticholinergic side effects as outcomes.",
    terms: ["last-days-of-life-care"], technologies: ["syringe-drivers", "palliative-care"],
    bottlenecks: ["b-palliative"],
    links: [SILENCE_2021, NICE_NG31, KOREA_LAST_DAYS_2020] }),
  // Added in the protocol fill round, 11 November 2026: both trial abstracts and the BTS 2023 guideline were read that day.
  idea({ id: "idea-upgrade-daily-pleural-catheter-drainage-offered", name: "Daily drainage of an indwelling pleural catheter offered to everyone whose lung re-expands and who wants the catheter out", maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 2,
    sections: ["supportive-care"], tags: T("proven-unevenly-used", "moderate"),
    tldr: "People with fluid around the lung from cancer can have a small tube left in to drain it at home. In two randomised trials, draining it every day rather than less often doubled or more than doubled how often the fluid stopped for good, without making breathlessness worse. The British guideline now recommends it where removing the tube matters to the person; how often it is offered is not measured.",
    summary: "Current practice. Home drainage is often done every other day, three times a week, or when breathless. The BTS guideline for pleural disease (2023) recommends daily drainage where catheter removal is a priority (conditional), and advises that daily drainage is not needed to control breathlessness (strong, by consensus).\n\nThe trials. ASAP randomised 149 people to daily or every-other-day drainage: autopleurodesis 47% against 24% (P = 0.003), with a shorter median time to it (54 against 90 days) and no difference in adverse events, quality of life or satisfaction. AMPLE-2 randomised 87 people to daily or symptom-guided drainage: breathlessness did not differ, spontaneous pleurodesis by 6 months was 44.2% against 15.9%, and EQ-5D-5L quality of life was better with daily drainage.\n\nThe gap. How often daily drainage is offered, and to whom, has not been measured.",
    hypothesis: "Offering daily drainage, with the trade-off explained, to everyone with an indwelling pleural catheter and an expandable lung raises the proportion whose catheter is removed within 3 months, without worse breathlessness or more infection.",
    rationale: "Two randomised trials agree, the guideline recommends it conditionally, and the cost is more drainage bottles and nursing or carer time. The choice belongs to the patient, so the change is in what is offered.",
    test: "An audit of drainage regimens offered and chosen across pleural services before and after a standard decision aid, with catheter removal at 3 months, infection and patient-reported breathlessness as outcomes.",
    technologies: ["indwelling-pleural-catheters"], terms: ["pleural-effusion"],
    bottlenecks: ["b-palliative", "b-knowledge-diffusion"],
    related: ["indwelling-pleural-catheter-drainage-at-home"],
    links: [
      doi("Wahidi et al., Randomized Trial of Pleural Fluid Drainage Frequency in Patients with Malignant Pleural Effusions: the ASAP trial (Am J Respir Crit Care Med 2017)", "10.1164/rccm.201607-1404OC"),
      doi("Muruganandan et al., Aggressive versus symptom-guided drainage of malignant pleural effusion via indwelling pleural catheters (AMPLE-2): an open-label randomised trial (Lancet Respir Med 2018)", "10.1016/S2213-2600(18)30288-1"),
      doi("Roberts et al., British Thoracic Society Guideline for pleural disease (Thorax 2023)", "10.1136/thorax-2022-219784"),
    ] }),
];

